def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not points:
        return out
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    frame = grid[r0][c0]
    inner = next((v for r, row in enumerate(grid) for c, v in enumerate(row)
                  if r0 < r < r1 and c0 < c < c1 and v not in (0, frame)), frame)
    thickness = 0
    for r in range(r0, r1 + 1):
        if all(grid[r][c] == frame for c in range(c0, c1 + 1)):
            thickness += 1
        else:
            break
    for r in range(r1, r0 - 1, -1):
        if all(grid[r][c] == frame for c in range(c0, c1 + 1)):
            thickness = min(thickness, r1 - r + 1)
        else:
            break
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if grid[r][c] != frame and grid[r][c] != inner:
                return out
    for r in range(max(0, r0 - thickness), min(len(grid), r1 + thickness + 1)):
        for c in range(max(0, c0 - thickness), min(len(grid[0]), c1 + thickness + 1)):
            if not (r0 <= r <= r1 and c0 <= c <= c1):
                out[r][c] = inner
    return out


